WITH filtered AS (SELECT *, INITCAP(TRIM(account_type)) account_type_title, CONCAT_WS('-', account_type, status) account_type_status_key FROM accounts WHERE opened_date >= DATE '2023-06-27' AND status IS NOT NULL), deduped AS (SELECT id, customer_id, account_type, balance, opened_date, status, account_type_title FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type, status ORDER BY opened_date NULLS FIRST, id) AS rank_in_group FROM filtered) t WHERE rank_in_group = 1), kept AS (SELECT s.* FROM deduped s WHERE EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_time <= s.opened_date)), latest_match AS (SELECT s.*, x.txn_type, x.txn_time FROM kept s JOIN LATERAL (SELECT c.txn_type, c.txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE), eligible AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_time <= s.txn_time)) SELECT * FROM (SELECT customer_id, txn_type, balance FROM eligible) src PIVOT (SUM(balance) AS total, COUNT(1) AS cnt FOR txn_type IN ('DEBIT', 'CREDIT'));
